from trytond.pool import Pool
from trytond.modules.html_report.html_report import HTMLReport
from trytond.wizard import Wizard, StateAction
from trytond.transaction import Transaction
import dominate.tags as tags
from weasyprint import HTML as WeasyHTML

from trytond.pool import Pool
from trytond.modules.html_report.html_report import HTMLReport
import dominate.tags as tags

class SupplierInvoiceCustomReport(HTMLReport):
    __name__ = 'account.supplier_invoice_custom'

    @classmethod
    def get_html(cls, records, data):
        # Reduced top/sides padding from 40px to 20px to push everything upward
        doc = tags.div(style="font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 12px; color: #333; padding: 20px 30px; position: relative; z-index: 1; max-width: 800px; margin: auto;")
        
        with doc:
            for invoice in records:
                # ==========================================
                # 0. WATERMARK LOGIC
                # ==========================================
                if invoice.state == 'paid':
                    tags.div("PAID", style="position: absolute; top: 40%; left: 25%; font-size: 120px; font-weight: bold; color: rgba(231, 76, 60, 0.15); transform: rotate(-45deg); z-index: 50; letter-spacing: 15px; pointer-events: none;")
                
                # ==========================================
                # 1. ORIGIN TRACING (PO ONLY)
                # ==========================================
                po_numbers = set()
                
                for line in invoice.lines:
                    if getattr(line, 'origin', None) and line.origin.__name__ == 'purchase.line':
                        pur_line = line.origin
                        if getattr(pur_line, 'purchase', None):
                            po_numbers.add(pur_line.purchase.number)

                po_str = ", ".join(filter(None, po_numbers)) or "N/A"

                # ==========================================
                # 2. HEADER: LOGO
                # ==========================================
                with tags.table(style="width: 100%; margin-bottom: 25px; border-collapse: collapse;"):
                    with tags.tr():
                        # --- LEFT COLUMN: Logo & Company Details ---
                        with tags.td(style="width: 60%; vertical-align: top; text-align: left;"):
                            logo_base64 = "data:image/png;base64,"
                            tags.img(src=logo_base64, style="max-width: 220px; height: auto;")
                            tags.div("Karachi, Sindh, Pakistan", style="color: #7f8c8d; font-size: 11px;")
                            tags.div("Main Rashid Minhas Road - 75950", style="color: #7f8c8d; font-size: 11px;")
                            tags.div("Phone: +923213742915, +9236900030", style="color: #7f8c8d; font-size: 11px;")
                            tags.div("Email: care@rayscreatiospk.com", style="color: #7f8c8d; font-size: 11px;")

                        # --- RIGHT COLUMN: Invoice Metadata (Pushed Down) ---
                        with tags.td(style="width: 40%; vertical-align: top; text-align: right; padding-top: 45px;"):
                            with tags.table(style="float: right; border-collapse: collapse; text-align: right; font-size: 12px;"):
                                with tags.tr():
                                    tags.td(tags.b("Invoice Date:"), style="padding: 2px 10px 2px 0; color: #7f8c8d; white-space: nowrap;")
                                    tags.td(str(invoice.invoice_date or getattr(invoice, 'date', 'N/A')), style="padding: 2px 0; white-space: nowrap;")
                                with tags.tr():
                                    tags.td(tags.b("Invoice No:"), style="padding: 2px 10px 2px 0; color: #7f8c8d; white-space: nowrap;")
                                    tags.td(invoice.number or invoice.reference or 'Draft', style="padding: 2px 0; font-weight: bold; color: #000; white-space: nowrap;")
                                with tags.tr():
                                    state_str = (invoice.state or 'draft').upper()
                                    state_color = "#e67e22" if state_str == 'POSTED' else "#e74c3c"
                                    tags.td(tags.b("Status:"), style="padding: 2px 10px 2px 0; color: #7f8c8d; white-space: nowrap;")
                                    tags.td(state_str, style="padding: 2px 0; font-weight: bold; color: " + state_color + "; white-space: nowrap;")

                # ==========================================
                # 3. TITLE (Full Width)
                # ==========================================
                tags.h2("SUPPLIER INVOICE", style="margin: 0 0 20px 0; font-size: 24px; color: #2980b9; border-bottom: 2px solid #2980b9; padding-bottom: 5px;")
                # ==========================================
                # 4. SUPPLIER & REFERENCE DETAILS
                # ==========================================
                with tags.table(style="width: 100%; margin-bottom: 30px; border-collapse: collapse;"):
                    with tags.tr():
                        with tags.td(style="width: 50%; vertical-align: top; padding-right: 20px;"):
                            tags.div("SUPPLIER DETAILS:", style="font-size: 11px; color: #7f8c8d; text-transform: uppercase; margin-bottom: 5px; font-weight: bold;")
                            supplier_name = invoice.party.name if invoice.party else 'Unknown Supplier'
                            tags.div(supplier_name, style="font-size: 14px; font-weight: bold; color: #2c3e50; margin-bottom: 3px;")
                            if invoice.party and invoice.party.addresses:
                                for addr in invoice.party.addresses:
                                    tags.div(addr.street or '', style="color: #555;")
                                    tags.div(addr.city or '', style="color: #555;")
                                    break
                        
                        with tags.td(style="width: 50%; vertical-align: top; padding-left: 20px; border-left: 2px solid #ecf0f1;"):
                            tags.div("REFERENCE DETAILS:", style="font-size: 11px; color: #7f8c8d; text-transform: uppercase; margin-bottom: 5px; font-weight: bold;")
                            with tags.table(style="width: 100%; font-size: 12px; line-height: 1.6;"):
                                with tags.tr():
                                    tags.td(tags.b("Purchase Order:"), style="width: 140px; color: #333;")
                                    tags.td(po_str, style="color: #555;")

                # ==========================================
                # 5. LINE ITEMS TABLE (Description Column Removed)
                # ==========================================
                with tags.table(style="width: 100%; border-collapse: collapse; margin-bottom: 25px;"):
                    with tags.thead():
                        with tags.tr(style="background-color: #2c3e50; color: #ffffff; text-align: left;"):
                            tags.th("Code", style="padding: 8px; font-weight: normal; width: 70px;")
                            tags.th("Product Name", style="padding: 8px; font-weight: normal; width: 150px;")
                            tags.th("Qty", style="padding: 8px; font-weight: normal; text-align: center; width: 60px;")
                            tags.th("Unit Price", style="padding: 8px; font-weight: normal; text-align: right; width: 90px;")
                            tags.th("Amount", style="padding: 8px; font-weight: normal; text-align: right; width: 90px;")
                    
                    with tags.tbody():
                        for index, line in enumerate(invoice.lines):
                            bg_color = "#f9f9f9" if index % 2 != 0 else "#ffffff"
                            prod_code = getattr(line.product, 'code', '') if getattr(line, 'product', None) else ''
                            prod_name = line.product.name if getattr(line, 'product', None) else ''
                            
                            with tags.tr(style=f"background-color: {bg_color}; border-bottom: 1px solid #ecf0f1;"):
                                tags.td(str(prod_code), style="padding: 8px; color: #7f8c8d;")
                                tags.td(str(prod_name), style="padding: 8px; font-weight: bold; color: #2c3e50;")
                                tags.td(str(line.quantity or ''), style="padding: 8px; text-align: center;")
                                tags.td(f"Rs. {line.unit_price:,.2f}" if line.unit_price else "", style="padding: 8px; text-align: right;")
                                tags.td(f"Rs. {line.amount:,.2f}" if line.amount else "", style="padding: 8px; text-align: right; font-weight: bold; color: #2c3e50;")

                # ==========================================
                # 6. REMARKS & TOTALS & FOOTER
                # ==========================================
                with tags.table(style="width: 100%; border-collapse: collapse; margin-bottom: 15px;"):
                    with tags.tr():
                        tags.td("", style="width: 50%;")
                        with tags.td(style="width: 50%;"):
                            with tags.table(style="width: 100%; border-collapse: collapse; font-size: 13px;"):
                                with tags.tr():
                                    tags.td("Subtotal:", style="padding: 6px 10px; text-align: right; color: #7f8c8d;")
                                    subtotal = f"Rs. {invoice.untaxed_amount:,.2f}" if getattr(invoice, 'untaxed_amount', None) else ""
                                    tags.td(subtotal, style="padding: 6px 10px; text-align: right;")
                                with tags.tr():
                                    tags.td("Tax:", style="padding: 6px 10px; text-align: right; color: #7f8c8d;")
                                    tax = f"Rs. {invoice.tax_amount:,.2f}" if getattr(invoice, 'tax_amount', None) else ""
                                    tags.td(tax, style="padding: 6px 10px; text-align: right;")
                                with tags.tr(style="background-color: #f4f6f7; font-size: 14px; font-weight: bold; border-top: 2px solid #2c3e50;"):
                                    tags.td("Total Due:", style="padding: 10px; text-align: right; color: #2c3e50;")
                                    total = f"Rs. {invoice.total_amount:,.2f}" if invoice.total_amount else ""
                                    tags.td(total, style="padding: 10px; text-align: right; color: #2980b9;")

                # Remarks Section (Placed below the totals matching your reference image)
                if invoice.description:
                    with tags.div(style="margin-bottom: 25px; font-size: 12px;"):
                        tags.span("Remarks: ", style="font-weight: bold; color: #333;")
                        tags.span(invoice.description, style="color: #555;")

                # Terms & Notes Footer
                with tags.table(style="width: 100%; border-collapse: collapse; page-break-inside: avoid;"):
                    with tags.tr():
                        with tags.td(style="padding-top: 10px;"):
                            tags.div("TERMS & NOTES", style="font-size: 11px; font-weight: bold; color: #7f8c8d; margin-bottom: 5px; text-transform: uppercase;")
                            tags.div("50% Advance Payment, 50% Before Delivery. Shipping, Duties & Taxes are not included in below price.", style="font-size: 10px; color: #555; margin-bottom: 4px;")
                            tags.div("Note: This is the computer generated document and does not require signature", style="font-size: 10px; font-style: italic; color: #95a5a6;")

        return doc.render()

# ==========================================
# 2. WIZARD CONTROLLER (Opens in New Tab)
# ==========================================
class PreviewInvoiceWizard(Wizard):
    'Invisible Wizard for Direct PDF Download'
    __name__ = 'account.invoice.preview_pdf_wizard'

    start_state = 'generate'
    generate = StateAction('custom_reports.act_preview_url') # Reuses the URL action from GL

    def do_generate(self, action):
        pool = Pool()
        Invoice = pool.get('account.invoice')
        Attachment = pool.get('ir.attachment')
        
        active_ids = Transaction().context.get('active_ids')
        if not active_ids:
            return action, {}
            
        invoices = Invoice.browse(active_ids)
        invoice = invoices[0] 
        
        # Call the custom HTML generator
        html_content = SupplierInvoiceCustomReport.get_html([invoice], {})
        
        # Convert to PDF directly via WeasyPrint
        pdf_bytes = WeasyHTML(string=html_content).write_pdf()
        
        filename = f"Supplier_Invoice_{invoice.number or invoice.id}.pdf"
        
        # ==========================================
        # NEW LOGIC: Prevent duplicate attachments
        # ==========================================
        existing_attachments = Attachment.search([
            ('resource', '=', f"account.invoice,{invoice.id}"),
            ('name', '=', filename)
        ])
        
        if existing_attachments:
            # Overwrite the existing attachment's data
            attachment = existing_attachments[0]
            Attachment.write([attachment], {
                'data': pdf_bytes
            })
        else:
            # Create a new attachment if none exists
            attachment = Attachment.create([{
                'name': filename,
                'type': 'data',
                'data': pdf_bytes,
                'resource': f"account.invoice,{invoice.id}",
            }])[0]
        
        # Open the new tab instantly via the existing web controller
        db_name = Transaction().database.name
        action['url'] = f"/{db_name}/custom_reports/preview/{attachment.id}"
        
        return action, {}